static void infrared_remote_mode_select_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) {
        return;
    }
    if (s_mode_roller != NULL) {
        uint16_t selected = lv_roller_get_selected(s_mode_roller);
        switch (s_popup_kind) {
        case IR_POPUP_BRAND:
            if (selected < infrared_remote_brand_count()) {
                s_ir_brand = (infrared_remote_brand_t)selected;
                infrared_remote_brand_apply();
                esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_STATE);
                if (err != ESP_OK) {
                    ESP_LOGW(SYSTEM_UI_TAG, "send infrared brand state command failed: %s", esp_err_to_name(err));
                }
            }
            break;
        case IR_POPUP_AC_MODE:
            if (selected < (sizeof(s_ac_modes) / sizeof(s_ac_modes[0]))) {
                s_ac_mode_index = (uint8_t)selected;
                infrared_remote_ac_mode_apply();
                esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_MODE);
                if (err != ESP_OK) {
                    ESP_LOGW(SYSTEM_UI_TAG, "send infrared mode command failed: %s", esp_err_to_name(err));
                }
            }
            break;
        case IR_POPUP_AIR_CONTROL:
            if (selected < (sizeof(s_air_controls) / sizeof(s_air_controls[0]))) {
                s_air_control_index = (uint8_t)selected;
                infrared_remote_air_control_apply();
                infrared_remote_air_value_apply();
            }
            break;
        case IR_POPUP_FAN_SPEED:
            if (selected < (sizeof(s_fan_speeds) / sizeof(s_fan_speeds[0]))) {
                s_fan_speed_index = (uint8_t)selected;
                infrared_remote_air_value_apply();
                esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_FAN);
                if (err != ESP_OK) {
                    ESP_LOGW(SYSTEM_UI_TAG, "send infrared fan command failed: %s", esp_err_to_name(err));
                }
            }
            break;
        case IR_POPUP_WIND_DIR:
            if (selected < (sizeof(s_wind_dirs) / sizeof(s_wind_dirs[0]))) {
                s_wind_dir_index = (uint8_t)selected;
                infrared_remote_air_value_apply();
                esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_WIND);
                if (err != ESP_OK) {
                    ESP_LOGW(SYSTEM_UI_TAG, "send infrared wind command failed: %s", esp_err_to_name(err));
                }
            }
            break;
        }
    }
    infrared_remote_mode_popup_close();
}

static void infrared_remote_popup_open(const char *options, uint8_t selected,
                                       ir_popup_kind_t kind, int x, int y, int w)
{
    if (ui_Container75 == NULL) {
        return;
    }
    if (s_mode_popup != NULL) {
        infrared_remote_mode_popup_close();
    }
    s_popup_kind = kind;

    s_mode_overlay = lv_obj_create(ui_Container75);
    if (s_mode_overlay == NULL) {
        return;
    }
    lv_obj_set_width(s_mode_overlay, 480);
    lv_obj_set_height(s_mode_overlay, 800);
    lv_obj_set_x(s_mode_overlay, 0);
    lv_obj_set_y(s_mode_overlay, 0);
    lv_obj_set_align(s_mode_overlay, LV_ALIGN_CENTER);
    lv_obj_clear_flag(s_mode_overlay, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_opa(s_mode_overlay, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_opa(s_mode_overlay, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_shadow_opa(s_mode_overlay, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_add_event_cb(s_mode_overlay, infrared_remote_mode_cancel_cb, LV_EVENT_CLICKED, NULL);

    s_mode_popup = lv_obj_create(s_mode_overlay);
    if (s_mode_popup == NULL) {
        infrared_remote_mode_popup_close();
        return;
    }
    lv_obj_set_width(s_mode_popup, w);
    lv_obj_set_height(s_mode_popup, 138);
    lv_obj_set_x(s_mode_popup, x);
    lv_obj_set_y(s_mode_popup, y);
    lv_obj_set_align(s_mode_popup, LV_ALIGN_CENTER);
    lv_obj_clear_flag(s_mode_popup, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_radius(s_mode_popup, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(s_mode_popup, lv_color_hex(0x080C08), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(s_mode_popup, 245, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_color(s_mode_popup, lv_color_hex(0xF0C430), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_opa(s_mode_popup, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(s_mode_popup, 3, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(s_mode_popup, 6, LV_PART_MAIN | LV_STATE_DEFAULT);

    s_mode_roller = lv_roller_create(s_mode_popup);
    if (s_mode_roller == NULL) {
        infrared_remote_mode_popup_close();
        return;
    }
    lv_obj_set_width(s_mode_roller, w - 26);
    lv_obj_set_height(s_mode_roller, 118);
    lv_obj_set_align(s_mode_roller, LV_ALIGN_CENTER);
    lv_roller_set_options(s_mode_roller, options, LV_ROLLER_MODE_INFINITE);
    lv_roller_set_visible_row_count(s_mode_roller, 3);
    lv_roller_set_selected(s_mode_roller, selected, LV_ANIM_OFF);
    lv_obj_set_style_bg_opa(s_mode_roller, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_opa(s_mode_roller, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_color(s_mode_roller, lv_color_hex(0x7C817A), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_font(s_mode_roller, &ui_font_Font2, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(s_mode_roller, lv_color_hex(0x303430), LV_PART_SELECTED | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(s_mode_roller, 255, LV_PART_SELECTED | LV_STATE_DEFAULT);
    lv_obj_set_style_text_color(s_mode_roller, lv_color_hex(0xF0C430), LV_PART_SELECTED | LV_STATE_DEFAULT);
    lv_obj_set_style_text_font(s_mode_roller, &ui_font_Font2, LV_PART_SELECTED | LV_STATE_DEFAULT);
    lv_obj_add_event_cb(s_mode_roller, infrared_remote_mode_select_cb, LV_EVENT_CLICKED, NULL);
}

static void infrared_remote_brand_long_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_LONG_PRESSED) {
        infrared_remote_popup_open(infrared_remote_brand_options(), (uint8_t)s_ir_brand,
                                   IR_POPUP_BRAND, -110, -220, 176);
    }
}

static void infrared_remote_brand_click_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED || s_mode_popup != NULL) {
        return;
    }
    esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_STATE);
    if (err != ESP_OK) {
        ESP_LOGW(SYSTEM_UI_TAG, "send infrared current state command failed: %s", esp_err_to_name(err));
    }
}

static void infrared_remote_ac_mode_long_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_LONG_PRESSED) {
        infrared_remote_popup_open(IR_AC_MODE_OPTIONS, s_ac_mode_index, IR_POPUP_AC_MODE, -110, -53, 176);
    }
}

static void infrared_remote_ac_mode_click_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED || s_mode_popup != NULL) {
        return;
    }
    esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_MODE);
    if (err != ESP_OK) {
        ESP_LOGW(SYSTEM_UI_TAG, "send infrared mode command failed: %s", esp_err_to_name(err));
    }
}

static void infrared_remote_air_control_long_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_LONG_PRESSED) {
        infrared_remote_popup_open(IR_AIR_CONTROL_OPTIONS, s_air_control_index, IR_POPUP_AIR_CONTROL, -100, 47, 138);
    }
}

static void infrared_remote_air_value_long_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_LONG_PRESSED) {
        return;
    }
    if (s_air_control_index == 0) {
        infrared_remote_popup_open(IR_FAN_SPEED_OPTIONS, s_fan_speed_index, IR_POPUP_FAN_SPEED, 150, 47, 138);
    } else {
        infrared_remote_popup_open(IR_WIND_DIR_OPTIONS, s_wind_dir_index, IR_POPUP_WIND_DIR, 140, 47, 188);
    }
}

static void infrared_remote_air_value_click_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED || s_mode_popup != NULL) {
        return;
    }
    infrared_remote_action_t action = (s_air_control_index == IR_REMOTE_AIR_FAN) ?
                                      IR_REMOTE_ACTION_FAN : IR_REMOTE_ACTION_WIND;
    esp_err_t err = infrared_remote_send_action(action);
    if (err != ESP_OK) {
        ESP_LOGW(SYSTEM_UI_TAG, "send infrared air command failed: %s", esp_err_to_name(err));
    }
}

static void infrared_remote_temperature_apply(void)
{
    if (ui_Label11 != NULL) {
        lv_label_set_text_fmt(ui_Label11, "%d", s_ir_temperature);
    }
}

static void infrared_remote_temperature_dec_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) {
        return;
    }
    if (s_ir_temperature > IR_TEMPERATURE_MIN) {
        s_ir_temperature--;
        infrared_remote_temperature_apply();
        esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_TEMP_DOWN);
        if (err != ESP_OK) {
            ESP_LOGW(SYSTEM_UI_TAG, "send infrared temperature command failed: %s", esp_err_to_name(err));
        }
    }
}

static void infrared_remote_temperature_inc_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) {
        return;
    }
    if (s_ir_temperature < IR_TEMPERATURE_MAX) {
        s_ir_temperature++;
        infrared_remote_temperature_apply();
        esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_TEMP_UP);
        if (err != ESP_OK) {
            ESP_LOGW(SYSTEM_UI_TAG, "send infrared temperature command failed: %s", esp_err_to_name(err));
        }
    }
}

static void infrared_remote_power_apply(void)
{
    const uint32_t bg_color = s_ir_power_on ? 0xF8AC10 : 0x384038;
    const uint32_t text_color = s_ir_power_on ? 0x000000 : 0xE84D41;
    const char *text = s_ir_power_on ? "ON" : "OFF";

    if (ui_Button17 != NULL) {
        lv_obj_set_style_bg_color(ui_Button17, lv_color_hex(bg_color),
                                  LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(ui_Button17, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
    }
    if (ui_Container50 != NULL) {
        lv_obj_set_style_bg_color(ui_Container50, lv_color_hex(bg_color),
                                  LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(ui_Container50, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
    }
    if (ui_Label9 != NULL) {
        lv_label_set_text(ui_Label9, text);
        lv_obj_set_style_text_color(ui_Label9, lv_color_hex(text_color),
                                    LV_PART_MAIN | LV_STATE_DEFAULT);
    }
}

static void infrared_remote_power_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) {
        return;
    }
    s_ir_power_on = !s_ir_power_on;
    infrared_remote_power_apply();
    esp_err_t err = infrared_remote_send_action(IR_REMOTE_ACTION_POWER);
    if (err != ESP_OK) {
        ESP_LOGW(SYSTEM_UI_TAG, "send infrared power command failed: %s", esp_err_to_name(err));
    }
}

static void infrared_remote_back_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) {
        return;
    }
    (void)system_ui_hide_infrared_remote();
}

