esp_err_t system_ui_create_infrared_remote_locked(void)
{
    (void)infrared_remote_ir_test_prepare_idle_gpio();
    ui_Screen3_screen_init();
    ESP_RETURN_ON_FALSE(ui_Screen3 != NULL, ESP_ERR_NO_MEM,
                        SYSTEM_UI_TAG, "create infrared remote screen failed");
    s_ui.infrared_remote_screen = ui_Screen3;
    ESP_LOGI(SYSTEM_UI_TAG, "infrared remote screen created");
    return ESP_OK;
}

void system_ui_delete_infrared_remote_locked(void)
{
    infrared_remote_ir_test_deinit();
    ui_Screen3_screen_destroy();
    s_ui.infrared_remote_screen = NULL;
    s_ui.infrared_remote_visible = false;
}

esp_err_t system_ui_show_infrared_remote(void)
{
    ESP_RETURN_ON_FALSE(s_ui.started && s_ui.infrared_remote_screen, ESP_ERR_INVALID_STATE,
                        SYSTEM_UI_TAG, "infrared remote screen not available");
    ESP_RETURN_ON_FALSE(!display_service_has_exclusive_session(), ESP_ERR_INVALID_STATE,
                        SYSTEM_UI_TAG, "exclusive display session active");
    ESP_RETURN_ON_ERROR(system_ui_lock(), SYSTEM_UI_TAG, "lock failed");
    s_ui.infrared_remote_visible = true;
    system_ui_load_screen_locked(s_ui.infrared_remote_screen);
    system_ui_unlock();
    return ESP_OK;
}

esp_err_t system_ui_hide_infrared_remote(void)
{
    ESP_RETURN_ON_FALSE(s_ui.started && s_ui.home_screen, ESP_ERR_INVALID_STATE,
                        SYSTEM_UI_TAG, "home screen not available");
    ESP_RETURN_ON_ERROR(system_ui_lock(), SYSTEM_UI_TAG, "lock failed");
    s_ui.infrared_remote_visible = false;
    ui_squareline_show_page(ui_squareline_current_page());
    system_ui_load_screen_locked(s_ui.home_screen);
    system_ui_unlock();
    return ESP_OK;
}
